-- =====================================================================
-- EDU — 02-reference-data.sql   (PostgreSQL)
-- Reference data every environment needs, generated by
-- database/sql/generate.sh from the app's own seeders @ 761c3f9:
-- 10 roles, 11 permissions + 30 role grants (spatie),
-- 3 states, 5 districts, 22 complaint categories, 10 school and
-- 12 teacher rating components.
-- Import AFTER 01-schema.sql into the same database. ON CONFLICT DO
-- NOTHING, so re-importing is harmless. Creates NO user accounts — see 03.
-- =====================================================================

SET client_encoding = 'UTF8';
SET search_path = public;

BEGIN;









-- Move each id sequence past the explicit ids inserted above
SELECT setval(pg_get_serial_sequence('public.roles', 'id'), COALESCE((SELECT MAX(id) FROM public.roles), 1), (SELECT MAX(id) IS NOT NULL FROM public.roles));
SELECT setval(pg_get_serial_sequence('public.permissions', 'id'), COALESCE((SELECT MAX(id) FROM public.permissions), 1), (SELECT MAX(id) IS NOT NULL FROM public.permissions));
SELECT setval(pg_get_serial_sequence('public.states', 'id'), COALESCE((SELECT MAX(id) FROM public.states), 1), (SELECT MAX(id) IS NOT NULL FROM public.states));
SELECT setval(pg_get_serial_sequence('public.districts', 'id'), COALESCE((SELECT MAX(id) FROM public.districts), 1), (SELECT MAX(id) IS NOT NULL FROM public.districts));
SELECT setval(pg_get_serial_sequence('public.complaint_categories', 'id'), COALESCE((SELECT MAX(id) FROM public.complaint_categories), 1), (SELECT MAX(id) IS NOT NULL FROM public.complaint_categories));
SELECT setval(pg_get_serial_sequence('public.school_rating_components', 'id'), COALESCE((SELECT MAX(id) FROM public.school_rating_components), 1), (SELECT MAX(id) IS NOT NULL FROM public.school_rating_components));
SELECT setval(pg_get_serial_sequence('public.teacher_rating_components', 'id'), COALESCE((SELECT MAX(id) FROM public.teacher_rating_components), 1), (SELECT MAX(id) IS NOT NULL FROM public.teacher_rating_components));

COMMIT;
